      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10/22~30) 서울/수도권 거주 만 20~29세 남성) 주류 좌담회 ( 친구와 함께 참석필수)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.16. 15:04\n조회 63\n구독\n10/22~30) 서울/수도권 거주 만 20~39세 남성) 주류 좌담회 ( 친구와 함께 참석필수)\n29세~39세 남성 / 동성 친구4명 참여가능자 부족 합니다.\n(친구와 함께 참여하는) 진행하고자 하오니 많은 신청 부탁드립니다.\n1. 대상자 조건\n서울/수도권 거주 만 20~39세 남성\n월 1~2회 이상 도수 6% 이상 RTD 또는 하이볼을 즐기는 음용자\n평소 함께 술을 마시는 실제 친구와 함께 참여가능한분 (연인, 배우자 포함 가능)\n편맥, 홈술/집모임, 프리드링킹(술자리 전 가볍게 마시는 음주)등 자주 즐기시는 분 우대\n※ RTD(Ready-to-Drink)란?\n캔 또는 병 형태의 즉음용 혼합주\n예: 짐빔 하이볼, 산토리 하이볼, 잭다니엘 콜라,써머스비, KGB, 별빛청하 등등\n일반 맥주, 소주, 전통주는 제외\n2. 그룹 구성 조건\n참석자는 본인을 포함하여 총 4명의 친구와 함께 참석해야하며, 아래 중 1가지 구성으로만 참여 가능합니다.\n남성 4명\n3. 진행 일정\n10월22일 ~ 30일 중 하루 진행예정\n세부 일정은 대상자 선정 후 개별 안내\n4. 진행 장소\n2호선 5호선 충정로역 부근\n5. 사례비\n사례비: 7만원\n1인당 7만원씩 지급입니다 !\n6. 신청시 기재사항\n성함\n나이\n연락처\n거주지역\n직업\n함께 참여 가능한 친구 구성 선택 (본인포함)\n1.남성 4명\n함께 참여 예정인 분들과의 관계 (예: 친구, 직장동료, 동창, 연인, 배우자 등)\nhttps://forms.gle/WMi4A2Sh5EweBNEq5\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구의 더 많은 인기글 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.10.16. 16:54 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n10/22~30) 서울/수도권 거주 만 30~39세 남성) 주류 좌담회 ( 친구와 함께 참석필수)\n좌담회알바좌담회카페\n26.10.16.\n댓글\n1\n10/22~30) 서울/수도권 거주 만 20~29세 남성) 주류 좌담회 ( 친구와 함께 참석필수)\n좌담회알바좌담회카페\n26.10.16.\n댓글\n1\n만25~55세 남녀 프리랜서) 커피머신 관련 조사 (11월1쨰주)\n좌담회알바좌담회카페\n26.10.16.\n댓글\n1\n만25~55세 남녀 자영업자) 커피머신 관련 조사 (11월1쨰주)\n좌담회알바좌담회카페\n26.10.16.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
