      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n10/21 (수) 40대여성) 제과 맛테스트+미니좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.16. 16:35\n조회 164\n구독\n10/21 (수) 40대여성) 제과 맛테스트+미니좌담회\n신청하신분은 재신청 안하셔도 됩니다\n<대상 조건>\n1. 서울/수도권 거주자\n2. 40~49세 여성\n3. 카스타드, 몽쉘 등 베이커리형 제과 주 1회이상 자주 섭취하시는분\n<설문조사 일시>\n10/21(수), 아래 시간 중 1회 참석 (조사 시간 15분전까지 도착 필요, 다같이 모여서 한 번에 조사장 들어갑니다.)\n1) 오전11시 2) 오후 2 3) 오후 4시30분 4) 오후 7시\n-소요시간: 맛테스트 60분 + 추가 좌담회 20분\n-장소: 강서구 마곡나루역 500m 내\n<사례비>\n맛테스트 3만원, 추가 좌담회 선정될 시 5천원 추가 / 조사 다음날 계좌로 송금\n<신청 방법>\n아래 URL에 접속하여 설문 응답 진행해주세요. (스마트폰에서도 응답 가능)\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://survey-insight.com/?ACCESS_KEY=1370b79f-1dc5-4eae-b81d-2abb0d99cfca&UID=\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n# 설문 종료 후 조건에 맞는 분께 개별적으로 연락 드릴 예정이며, 조건이 맞지 않거나 신청이 많아 조기 마감될 경우 세부 참석 조건 묻는 전화가 가지 않을 수도 있습니다.\n# 설문응답 마지막 개인정보 입력 시 소개자/소개받은 곳 이름은 필수로 입력하셔야 합니다..\n# 조사 참석 시 반드시 신분증을 지참해 주시기 바랍니다.\n## 최종 선정이 된 후 당일 불참, 연락이 두절될 경우 향후 조사 참석 시 불이익이 있을 수 있습니다.\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.10.16. 16:52 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n10/13~23) 국내 전문대학교, 대학원 정보보호 관련 학과 대학생,대학원생 대상 온라인조사\n좌담회알바좌담회카페\n26.10.16.\n댓글\n1\n10/21 (수) 40대여성) 제과 맛테스트+미니좌담회\n좌담회알바좌담회카페\n26.10.16.\n댓글\n1\n10/29) 25~49)단백질쉐이크 식품관련 갱서베이-첫째자녀가 초,중,고등 자녀 유자녀 여성\n좌담회알바좌담회카페\n26.10.16.\n댓글\n1\n10/29) 25~49)단백질쉐이크 식품관련 갱서베이-첫째자녀가 미취학자녀 유자녀 여성\n좌담회알바좌담회카페\n26.10.16.\n댓글\n1\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
